def transform(grid):
    """Replace each isolated marker with the task's five-cell template."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(range(10), key=lambda v: sum(cell == v for row in g for cell in row))

    # Locate the five-cell straight template; its direction determines stamp direction.
    template = None
    for r in range(h):
        for c in range(w - 4):
            vals = g[r][c:c + 5]
            if all(v != bg for v in vals):
                template = ('h', r, c, vals[:])
                break
        if template:
            break
    if template is None:
        for r in range(h - 4):
            for c in range(w):
                vals = [g[rr][c] for rr in range(r, r + 5)]
                if all(v != bg for v in vals):
                    template = ('v', r, c, vals)
                    break
            if template:
                break
    if template is None:
        raise ValueError('five-cell template not found')

    direction, tr, tc, pattern = template
    template_cells = {(tr + (i if direction == 'v' else 0), tc + (i if direction == 'h' else 0)) for i in range(5)}
    markers = [(r, c) for r in range(h) for c in range(w)
               if g[r][c] != bg and (r, c) not in template_cells]
    for r, c in markers:
        start = (c if direction == 'h' else r) - 2
        for i, value in enumerate(pattern):
            rr, cc = (r, start + i) if direction == 'h' else (start + i, c)
            g[rr][cc] = value
    return g

